# Here we define the Conv1D block, which is GPT2's custom implementation for a Linear MLP Layer.

# In[6]:


class Conv1D(nn.Module):
    def __init__(self, nf, nx):
        super().__init__()
        self.nf = nf
        w = torch.empty(nx, nf)
        nn.init.normal_(w, std=0.02)
        self.weight = nn.Parameter(w)
        self.bias = nn.Parameter(torch.zeros(nf))

    def forward(self, x):
        size_out = x.size()[:-1] + (self.nf,)
        x_view = x.view(-1, x.size(-1))
        result = x_view @ self.weight + self.bias
        return result.view(*size_out)


# Then, we start modifying the base model architecture to create its MoE version. First, we define an single expert network, which is the standard feed-forward expert block. Its architecture looks something like this:
# 
# x → Linear → GELU → Linear → output

# In[7]:


class ExpertLayer(nn.Module):
    def __init__(self, input_dim, hidden_dim):
        super().__init__()
        self.c_fc = Conv1D(hidden_dim, input_dim)
        self.c_proj = Conv1D(input_dim, hidden_dim)
        self.act = nn.GELU(approximate="tanh")

    def forward(self, x):
        hidden = self.c_fc(x)
        hidden = self.act(hidden)
        output = self.c_proj(hidden)
        return output


# Now a single expert network's architecture has been defined, we define the architecture of a MoE layer.
# 
# Note the design of our routing network, specifically its behavior in the forward pass. We're using the top-k routing strategy. The router network takes in the input token, predicts logits for each expert network, and then use softmax to convert the logit to a probability. Then, it picks the top-k experts during the forward pass to actually pass the input token in, scales the output by the normalized probability score of the respective top-k networks, and sum them to get the final output from that expert layer.

# Here, we also define

# In[8]:


import torch
import torch.nn as nn
import torch.nn.functional as F

class MixtureOfExperts(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_experts=12, top_k=4, balance_loss_weight=0.01):
        super().__init__()
        self.input_dim = input_dim
        self.hidden_dim = hidden_dim
        self.num_experts = num_experts
        self.top_k = top_k
        self.balance_loss_weight = balance_loss_weight

        self.experts = nn.ModuleList([
            ExpertLayer(input_dim, hidden_dim)
            for _ in range(num_experts)
        ])

        self.router = nn.Linear(input_dim, num_experts)

    def forward(self, x):
        batch_size, seq_len, d_model = x.shape
        device = x.device

        # === Step 1: Compute routing scores ===
        router_logits = self.router(x)  # [B, T, E]
        routing_weights = F.softmax(router_logits, dim=-1)  # [B, T, E]

        # === Step 2: Top-k selection per token ===
        topk_weights, topk_indices = torch.topk(routing_weights, self.top_k, dim=-1)  # [B, T, k]
        topk_weights /= topk_weights.sum(dim=-1, keepdim=True)  # normalize

        # Flatten inputs for easier processing
        x_flat = x.view(-1, d_model)  # [B*T, D]
        topk_indices_flat = topk_indices.view(-1, self.top_k)  # [B*T, k]
        topk_weights_flat = topk_weights.view(-1, self.top_k)  # [B*T, k]

        output_flat = torch.zeros_like(x_flat)  # [B*T, D]
        expert_counts = torch.zeros(self.num_experts, device=device)

        # === Step 3: Route each token to its top-k experts ===
        for expert_id in range(self.num_experts):
            # Mask of tokens where this expert is selected
            mask = (topk_indices_flat == expert_id)  # [B*T, k]
            positions = torch.nonzero(mask, as_tuple=False)  # [N, 2]

            if positions.shape[0] == 0:
                continue

            token_indices = positions[:, 0]  # [N]
            slot_indices = positions[:, 1]   # [N]

            x_selected = x_flat[token_indices]  # inputs for this expert
            y_selected = self.experts[expert_id](x_selected)  # [N, D]

            weights = topk_weights_flat[token_indices, slot_indices]  # [N]
            output_flat[token_indices] += weights.unsqueeze(1) * y_selected

            expert_counts[expert_id] = token_indices.numel()

        # === Step 4: Reshape back and compute aux losses ===
        output = output_flat.view(batch_size, seq_len, d_model)

        # Load balancing loss
        num_tokens = batch_size * seq_len
        expert_fractions = expert_counts / (num_tokens * self.top_k)
        balance_loss = self.num_experts * torch.sum(expert_fractions ** 2)

        # Router z-loss
        router_z_loss = torch.mean(torch.sum(router_logits ** 2, dim=-1))

        # Total aux loss
        aux_loss = self.balance_loss_weight * (balance_loss + 0.001 * router_z_loss)
        self.aux_loss = aux_loss

        return output, self.aux_loss


# Now that the Expert lahyer is defined, we are going to build a custom Transformer block for GPT-2 that replaces the standard MLP with a Mixture-of-Experts (MoE), while preserving the rest of the GPT-2 architecture (like self-attention and layer norms).
# 
# Here, take note how we're initializing the weight of the expert layer. We are taking the weights of the original MLPs from the pretrained GPT2, dividing the weights by the number of experts in each layer, and using the scaled down weights as the intialized weights of each expert network. The initialization of the router network weights is more straightforward -- it is simply randomly initialized by a normal distribution.
# 

# In[9]:


class GPT2MoEBlock(nn.Module):
    def __init__(self, original_block, num_experts=12, top_k=4, balance_loss_weight=0.01):
        super().__init__()

        # Retain the same attention block and layer norm before the attention block and the MLP layer
        self.attn = original_block.attn
        self.ln_1 = original_block.ln_1
        self.ln_2 = original_block.ln_2
        hidden_size = original_block.ln_1.weight.size(0)
        intermediate_size = original_block.mlp.c_fc.weight.shape[1]

        # we will use the MoE block that we just defined to replace the MLPs in the attention block
        self.mlp = MixtureOfExperts(
            input_dim=hidden_size,
            hidden_dim=intermediate_size,
            num_experts=num_experts,
            top_k=top_k,
            balance_loss_weight=balance_loss_weight
        )

        # here, we loop through each expert block in the Mixture of expert layer and initialize their weights & biases
        for expert in self.mlp.experts:
            with torch.no_grad():

                # copy the weights of the original MLP block's up projection layer to each expert and normalize by division of the number of experts
                expert.c_fc.weight.data = original_block.mlp.c_fc.weight.clone().to(expert.c_fc.weight.device) / num_experts

                # copy the bias of the original MLP block's up projection layer to each expert and normalize by division of the number of experts
                expert.c_fc.bias.data = original_block.mlp.c_fc.bias.clone().to(expert.c_fc.bias.device) / num_experts

                # copy the weights of the original MLP block's down projection layer to each expert and normalize by division of the number of experts
                expert.c_proj.weight.data = original_block.mlp.c_proj.weight.clone().to(expert.c_proj.weight.device) / num_experts

                # copy the bias of the original MLP block's down projection layer to each expert and normalize by division of the number of experts
                expert.c_proj.bias.data = original_block.mlp.c_proj.bias.clone().to(expert.c_proj.bias.device) / num_experts

        with torch.no_grad():
            # initialize the router network's weights via random noise through a normal distribution
            nn.init.normal_(self.mlp.router.weight, mean=0.0, std=0.01)

        device = next(original_block.parameters()).device
        self = self.to(device)

    def forward(
        self,
        hidden_states,
        layer_past=None,
        attention_mask=None,
        head_mask=None,
        encoder_hidden_states=None,
        encoder_attention_mask=None,
        use_cache=False,
        output_attentions=False,
        **kwargs
    ):

        # Residual connection. this is the input
        residual = hidden_states

        # Layer norm before passing input into attention
        hidden_states = self.ln_1(hidden_states)

        # arguments for the attention block
        attn_args = {
            "hidden_states": hidden_states,
            "layer_past": layer_past,
            "attention_mask": attention_mask,
            "head_mask": head_mask,
            "use_cache": use_cache,
            "output_attentions": output_attentions,
        }

        # passing in redundant arguments
        for key in kwargs:
            if key in ["position_ids", "position_embeddings"]:
                attn_args[key] = kwargs[key]

        # outputs from the attention block
        attn_outputs = self.attn(**attn_args)
        attn_output = attn_outputs[0]
        outputs = attn_outputs[1:]

        # Residual connection mechanism, adding the residual back to the input
        hidden_states = attn_output + residual

        # Second residual connection
        residual = hidden_states

        # Layer norm post attention block
        hidden_states = self.ln_2(hidden_states)

        # Passing into the mixture of experts layer
        hidden_states_moe, aux_loss = self.mlp(hidden_states)
        hidden_states = hidden_states_moe + residual

        # second residual connection
        if use_cache:
            outputs = (hidden_states,) + outputs
        else:
            outputs = (hidden_states,) + outputs[1:]
        return outputs


# Now all components of the GPT-2 MoE architecture have been defined, we can apply the architectural modifications onto the original GPT-2 architecture. Note that we can make our own design decisions on which specific layers we want to apply the MoE modifications on. We can do a very dense MoE modification by replacing every single MLP with a MoE block, or we can do a sparse MoE modification by replacing only several MLPs with a MoE block.
# 
# As a background, this is what the GPT-2 architecture looks like. It is essentially just a bunch of repeated, identical decoders stacked on top of each other. By picking the MLPs to replace with a MoE block, we're actually just picking the specific decoder blocks to do the MoE modification on.
# 
# Note that we can also pick the number of expert networks in each expert layers, as well as k as a hyperparameter to choose the top-k expert networks to do the forward pass on in each expert layer. Here, GPT-2 Large has 36 decoder blocks, and we're replacing MLPs with a 4-expert, top-2 expert network every 4 decoder blocks.
# 
# ![gpt2-sizes-hyperparameters-3.png](data:image/png;base64,)

# In[10]:


# Hyperparameters for expert layers
num_experts = 4
top_k = 2
total_layers = len(model.transformer.h)
layers_to_convert = [i for i in range(0, total_layers, 4)]
conversion_status = {idx: False for idx in layers_to_convert}
successful_layers = []

# convert every 4 decoder layer into its MoE version
for idx in layers_to_convert:
    original_block = model.transformer.h[idx]
    try:
        moe_block = GPT2MoEBlock(
            original_block,
            num_experts=num_experts,
            top_k=top_k
        )
        model.transformer.h[idx] = moe_block
        conversion_status[idx] = True
        successful_layers.append(idx)
        print(f"Layer {idx} successfully converted to MoE.")
    except Exception as e:
        pass

print(f"\nFinal model parameter count: {sum(p.numel() for p in model.parameters()):,}")



# As we can see, our final model has over 1 billion parameters now -- a much higher number than the 700M parameters the original GPT-2-Large architecture has due to the addition of all the experts! Here, we can also do an inference test to see what an output looks like.

