with torch.no_grad():
    moe_outputs = model.generate(
        input_ids,
        max_length=50,
        num_return_sequences=1,
        do_sample=True,
        temperature=0.7,
    )

moe_output = tokenizer.decode(moe_outputs[0], skip_special_tokens=True)
print(f"\nMoE output generated: {moe_output}")


# Finally, one thing that we'll have to do is to add the load balancing loss to the training loop, such that we can ensure a even distribution of tokens among the experts during inference. Here, we implement the load balancing loss by adding the auxiliary loss to the model's standard loss, such that the auxiliary loss can be seamlessly integrated into Huggingface's Trainer class.

# In[12]:


class GPT2MoEWithAuxLoss(nn.Module):
    def __init__(self, base_model, successful_layers):
        super().__init__()
        self.base_model = base_model
        self.successful_layers = successful_layers

    def forward(self, input_ids=None, attention_mask=None, labels=None, **kwargs):
        # Forward pass through base model
        outputs = self.base_model(input_ids=input_ids, attention_mask=attention_mask, labels=labels, **kwargs)

        # If labels are provided, compute auxiliary loss
        if labels is not None:
            loss = outputs.loss

            # Collect auxiliary losses
            aux_loss = torch.tensor(0.0, device=loss.device)
            for layer_idx in self.successful_layers:
                moe_layer = self.base_model.transformer.h[layer_idx]
                if hasattr(moe_layer, 'mlp') and hasattr(moe_layer.mlp, 'aux_loss'):
                    aux_loss += moe_layer.mlp.aux_loss

            # Add auxiliary loss to the main loss
            outputs.loss = loss + aux_loss

        return outputs

wrapped_model = GPT2MoEWithAuxLoss(model, successful_layers)


# ## Part III: Finetuning
# 
# As we can see in the inference result, the inference performance of the model significantly deteriorated from the original architecture. This is because although we initialized the weights of the expert networks by replicating the weights of the original NLPs, the model is still unfamiliar with its new architecture. What we need is a finetuning process to accustom the model with its new MoE architecture.

# In[13]:


from transformers import TrainingArguments, Trainer, DataCollatorForLanguageModeling
import os

# Create tensorboard log directory
log_dir = "./logs"
os.makedirs(log_dir, exist_ok=True)

training_args = TrainingArguments(
    output_dir="./results",
    num_train_epochs=2,
    per_device_train_batch_size=4,
    per_device_eval_batch_size=4,
    gradient_accumulation_steps=8,
    learning_rate=5e-5,
    warmup_ratio=0.1,
    fp16=True,
    logging_steps=10,
    save_strategy="steps",
    eval_strategy="steps",
    eval_steps=50,
    save_steps=100,
    load_best_model_at_end=True,
    metric_for_best_model="eval_loss",
    report_to=["tensorboard"],
    logging_dir="./logs",
    remove_unused_columns=False,
    save_safetensors=False,
)

# Data collator is still useful for dynamic padding
data_collator = DataCollatorForLanguageModeling(
    tokenizer=tokenizer,
    mlm=False  # We're doing causal language modeling
)

# Use regular Trainer with fixed datasets
trainer = Trainer(
    model=wrapped_model,
    args=training_args,
    train_dataset=tokenized_train_dataset, # We defined these tokenized dataset earlier from the SlimPajama dataset
    eval_dataset=tokenized_eval_dataset,
)

# Load the TensorBoard notebook extension
get_ipython().run_line_magic('load_ext', 'tensorboard')

# Launch TensorBoard
get_ipython().run_line_magic('tensorboard', '--logdir {log_dir}')

# Start training
print("Starting training...")
trainer.train()

wrapped_model.base_model.save_pretrained("./results/final-checkpoint")
